{"implementation":"def solve(case):
    nodes = case["nodes"]
    core = case["core_distance"]
    edges = []
    for index, item in enumerate(case["distances"]):
        u, v, distance = item
        weight = max(core[u], core[v], distance)
        edges.append((weight, index, u, v))
    edges.sort(key=lambda edge: (edge[0], edge[1]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    mst_edges = []
    total_weight = 0.0
    for weight, _, u, v in edges:
        root_u = find(u)
        root_v = find(v)
        if root_u == root_v:
            continue
        if rank[root_u] < rank[root_v]:
            root_u, root_v = root_v, root_u
        parent[root_v] = root_u
        if rank[root_u] == rank[root_v]:
            rank[root_u] += 1
        mst_edges.append([u, v, weight])
        total_weight += weight
        if len(mst_edges) == max(0, len(nodes) - 1):
            break
    return {"mst_edges": mst_edges, "total_weight": total_weight}"}
